function validate([grid]) {
  const n = grid.length;
  if (n < 2 || n > 100) return 'grid needs 2 to 100 rows.';
  if (grid.some(row => row.length !== n)) return 'grid must be square.';
  if (grid.some(row => row.some(v => v !== 0 && v !== 1))) return 'Each cell is 0 or 1.';
  if (grid[0][0] !== 0 || grid[0][1] !== 0) return 'The starting cells (0, 0) and (0, 1) must be open.';
  return null;
}

