function minimumMoves(grid) {
  const n = grid.length;
  const isOpen = (row, col) => row < n && col < n && grid[row][col] === 0;
  const seen = new Uint8Array(n * n * 2);
  let queue = [[0, 0, 0]];
  seen[0] = 1;
  let moves = 0;

  while (queue.length > 0) {
    const nextQueue = [];
    for (const [row, col, vertical] of queue) {
      if (row === n - 1 && col === n - 2 && vertical === 0) {
        return moves;
      }
      const options = [];
      if (vertical === 0) {
        if (isOpen(row, col + 2)) {
          options.push([row, col + 1, 0]);
        }
        if (isOpen(row + 1, col) && isOpen(row + 1, col + 1)) {
          options.push([row + 1, col, 0]);
          options.push([row, col, 1]);
        }
      } else {
        if (isOpen(row + 2, col)) {
          options.push([row + 1, col, 1]);
        }
        if (isOpen(row, col + 1) && isOpen(row + 1, col + 1)) {
          options.push([row, col + 1, 1]);
          options.push([row, col, 0]);
        }
      }
      for (const [nextRow, nextCol, nextVertical] of options) {
        const key = (nextRow * n + nextCol) * 2 + nextVertical;
        if (seen[key] === 0) {
          seen[key] = 1;
          nextQueue.push([nextRow, nextCol, nextVertical]);
        }
      }
    }
    queue = nextQueue;
    moves++;
  }
  return -1;
}

