function minimumMoves(grid) {
  // Bellman-Ford style relaxation over snakes stored as their two explicit cells.
  const n = grid.length;
  const free = (cell) => cell[0] >= 0 && cell[1] >= 0 && cell[0] < n && cell[1] < n && grid[cell[0]][cell[1]] === 0;
  const name = (snake) => snake.map(cell => cell.join(',')).join('|');
  const neighbours = (snake) => {
    const [a, b] = snake;
    const result = [];
    const right = [[a[0], a[1] + 1], [b[0], b[1] + 1]];
    if (right.every(free)) result.push(right);
    const down = [[a[0] + 1, a[1]], [b[0] + 1, b[1]]];
    if (down.every(free)) result.push(down);
    const horizontal = a[0] === b[0];
    if (horizontal && free([a[0] + 1, a[1]]) && free([a[0] + 1, a[1] + 1])) result.push([a, [a[0] + 1, a[1]]]);
    if (!horizontal && free([a[0], a[1] + 1]) && free([a[0] + 1, a[1] + 1])) result.push([a, [a[0], a[1] + 1]]);
    return result;
  };
  const dist = new Map([[name([[0, 0], [0, 1]]), 0]]);
  const snakes = new Map([[name([[0, 0], [0, 1]]), [[0, 0], [0, 1]]]]);
  let changed = true;
  while (changed) {
    changed = false;
    for (const [key, snake] of [...snakes]) {
      for (const next of neighbours(snake)) {
        const nk = name(next);
        if (!dist.has(nk) || dist.get(nk) > dist.get(key) + 1) {
          dist.set(nk, dist.get(key) + 1);
          snakes.set(nk, next);
          changed = true;
        }
      }
    }
  }
  const goal = name([[n - 1, n - 2], [n - 1, n - 1]]);
  return dist.has(goal) ? dist.get(goal) : -1;
}

