function generate(rand, size) {
  const n = size === 'large' ? 60 + Math.floor(rand() * 41) : 2 + Math.floor(rand() * 6);
  const density = size === 'large' ? 0.05 + rand() * 0.15 : rand() * 0.35;
  const grid = Array.from({ length: n }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)));
  grid[0][0] = 0;
  grid[0][1] = 0;
  if (rand() < 0.7) {
    grid[n - 1][n - 2] = 0;
    grid[n - 1][n - 1] = 0;
  }
  return [grid];
}
